SELECT DISTINCT cs_sub.canonical_smiles AS canonical_smiles, mol_sub.pref_name AS substrate_compound_name, mol_parent.pref_name AS parent_compound_name, met.met_conversion AS met_conversion, met.pathway_key AS pathway_key, met.organism AS organism, met.enzyme_name AS enzyme_name FROM metabolism met INNER JOIN compound_records cr_sub ON met.substrate_record_id = cr_sub.record_id INNER JOIN molecule_dictionary mol_sub ON cr_sub.molregno = mol_sub.molregno INNER JOIN compound_structures cs_sub ON mol_sub.molregno = cs_sub.molregno INNER JOIN compound_records cr_parent ON met.metabolite_record_id = cr_parent.record_id INNER JOIN molecule_dictionary mol_parent ON cr_parent.molregno = mol_parent.molregno WHERE met.enzyme_name = 'CYP1A2' ORDER BY canonical_smiles, substrate_compound_name, parent_compound_name, met_conversion, pathway_key, organism, enzyme_name LIMIT 200;
